pub fn count_vowels(s: &str) -> usize {
    s.chars()
        .filter(|c| matches!(c.to_ascii_lowercase(), 'a' | 'e' | 'i' | 'o' | 'u'))
        .count()
}

fn main() {
    println!("{}", count_vowels("Hello World"));
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_empty_string() {
        assert_eq!(count_vowels(""), 0);
    }

    #[test]
    fn test_all_vowels() {
        assert_eq!(count_vowels("aeiou"), 5);
        assert_eq!(count_vowels("AEIOU"), 5);
        assert_eq!(count_vowels("aeiouAEIOU"), 10);
    }

    #[test]
    fn test_no_vowels() {
        assert_eq!(count_vowels("bcdfghjklmnpqrstvwxyz"), 0);
        assert_eq!(count_vowels("BCDFGHJKLMNPQRSTVWXYZ"), 0);
    }

    #[test]
    fn test_mixed_letters() {
        assert_eq!(count_vowels("hello world"), 3);
        assert_eq!(count_vowels("rust programming"), 4);
        assert_eq!(count_vowels("The quick brown fox"), 5);
    }

    #[test]
    fn test_uppercase_letters() {
        assert_eq!(count_vowels("HELLO"), 2);
        assert_eq!(count_vowels("WORLD"), 1);
        assert_eq!(count_vowels("AEIOUaeiou"), 10);
    }
}
